// Mini cliente CDP para probar el juego con Chrome headless (sin dependencias)
const { spawn } = require('child_process');
const fs = require('fs');
const path = require('path');

const FILE = process.argv[2] || '/var/tmp/bench/ws-9Tqt6ywi/alquimia-web-reactiva.html';
const SHOT = process.argv[3] || '/tmp/opencode/shot.png';
const PORT = 9222 + Math.floor(Math.random() * 500);

const chrome = spawn('google-chrome', [
  '--headless=new', '--no-sandbox', '--disable-gpu', '--hide-scrollbars',
  '--window-size=1440,900', '--remote-debugging-port=' + PORT,
  '--user-data-dir=/tmp/opencode/chrome-profile-' + PORT,
  'file://' + FILE
], { stdio: ['ignore', 'pipe', 'pipe'] });

const sleep = ms => new Promise(r => setTimeout(r, ms));

(async () => {
  let target = null;
  for (let i = 0; i < 60; i++) {
    await sleep(300);
    try {
      const r = await fetch(`http://127.0.0.1:${PORT}/json/list`);
      const list = await r.json();
      target = list.find(t => t.type === 'page' && t.url.includes('alquimia'));
      if (target) break;
    } catch (e) {}
  }
  if (!target) { console.log('NO TARGET'); chrome.kill(); process.exit(1); }

  const ws = new WebSocket(target.webSocketDebuggerUrl);
  let id = 0;
  const pending = new Map();
  const logs = [];
  const errors = [];
  const send = (method, params = {}) => new Promise(res => {
    const mid = ++id;
    pending.set(mid, res);
    ws.send(JSON.stringify({ id: mid, method, params }));
  });

  ws.onmessage = ev => {
    const m = JSON.parse(ev.data);
    if (m.id && pending.has(m.id)) { pending.get(m.id)(m.result); pending.delete(m.id); }
    if (m.method === 'Runtime.consoleAPICalled') {
      logs.push(m.params.type + ': ' + m.params.args.map(a => a.value !== undefined ? a.value : (a.description || a.type)).join(' '));
    }
    if (m.method === 'Runtime.exceptionThrown') {
      errors.push(m.params.exceptionDetails.exception?.description || m.params.exceptionDetails.text);
    }
    if (m.method === 'Log.entryAdded' && m.params.entry.level === 'error') {
      errors.push('LOG: ' + m.params.entry.text);
    }
  };

  await new Promise(r => ws.onopen = r);
  await send('Runtime.enable');
  await send('Log.enable');
  await send('Page.enable');
  await sleep(1200);

  const evalJS = async expr => {
    const r = await send('Runtime.evaluate', { expression: expr, returnByValue: true, awaitPromise: true });
    if (r.exceptionDetails) return { error: r.exceptionDetails.exception?.description || r.exceptionDetails.text };
    return r.result?.value;
  };

  const out = {};
  out.title = await evalJS('document.title');
  out.elementos = await evalJS('ELEMENTS.length');
  out.recetas = await evalJS('RECIPES.length');
  out.iniciales = await evalJS('document.querySelectorAll("#mesa .el").length');
  out.biblioteca = await evalJS('document.querySelectorAll(".lib-item").length');

  // --- simular combinación: usar la API interna expuesta vía doCombine ---
  out.combinacion = await evalJS(`(function(){
    const a = document.querySelector('.el[data-id="prompt"]');
    const b = document.querySelector('.el[data-id="modelo"]');
    if(!a||!b) return 'no hay elementos base';
    const r = doCombine('prompt','modelo', 120, 120, [a,b]);
    return { r, descubiertos: state.discovered.size, tarjetas: document.querySelectorAll('#mesa .el').length };
  })()`);
  await sleep(300);
  out.trasCombinar = await evalJS('({n: state.discovered.size, cards: document.querySelectorAll("#mesa .el").length, lib: document.querySelectorAll(".lib-item").length})');

  // --- arrastrar desde la biblioteca a la mesa ---
  out.arrastre = await evalJS(`(function(){
    const it = document.querySelector('.lib-item[data-id="modelo"]');
    const rect = it.getBoundingClientRect();
    const mesaR = document.getElementById('mesa').getBoundingClientRect();
    const down = new PointerEvent('pointerdown',{clientX:rect.left+10,clientY:rect.top+10,bubbles:true,cancelable:true,pointerId:1});
    it.dispatchEvent(down);
    const mv = new PointerEvent('pointermove',{clientX:mesaR.left+400,clientY:mesaR.top+300,bubbles:true,cancelable:true,pointerId:1});
    window.dispatchEvent(mv);
    const up = new PointerEvent('pointerup',{clientX:mesaR.left+400,clientY:mesaR.top+300,bubbles:true,cancelable:true,pointerId:1});
    window.dispatchEvent(up);
    return document.querySelectorAll('#mesa .el').length;
  })()`);
  await sleep(200);
  out.trasArrastre = await evalJS('({cards: document.querySelectorAll("#mesa .el").length})');

  // --- pista, recetario, compartir ---
  out.pista = await evalJS('(function(){showHint(); return document.querySelectorAll(".toast").length})()');
  out.recetas = await evalJS('(function(){showRecipes(); return document.getElementById("modalTitle").textContent})()');
  out.codigo = await evalJS('shareCode().slice(0,30)');
  await evalJS('closeModal()');

  // --- persistencia ---
  out.saved = await evalJS('(function(){save(); return !!localStorage.getItem("alquimia-web-reactiva-v1")})()');

  // --- vista móvil ---
  await send('Emulation.setDeviceMetricsOverride', { width: 390, height: 844, deviceScaleFactor: 2, mobile: true });
  await sleep(500);
  out.movil = await evalJS('({libToggle: getComputedStyle(document.getElementById("libtoggle")).display, overflowX: document.documentElement.scrollWidth <= window.innerWidth})');

  await send('Emulation.clearDeviceMetricsOverride');
  await sleep(400);

  const shot = await send('Page.captureScreenshot', { format: 'png' });
  fs.writeFileSync(SHOT, Buffer.from(shot.data, 'base64'));

  console.log(JSON.stringify(out, null, 2));
  console.log('--- CONSOLE ---'); logs.slice(0, 25).forEach(l => console.log(l));
  console.log('--- ERRORES ---'); errors.forEach(e => console.log(e));
  console.log(errors.length ? 'RESULTADO: HAY ERRORES' : 'RESULTADO: sin errores');

  ws.close();
  chrome.kill();
  process.exit(errors.length ? 2 : 0);
})().catch(e => { console.error('FALLO', e); chrome.kill(); process.exit(1); });

