  const ev=async e=>{const r=await send('Runtime.evaluate',{expression:e,returnByValue:true,awaitPromise:true});
    return r.exceptionDetails? {ERR:r.exceptionDetails.exception?.description||r.exceptionDetails.text} : r.result?.value;};

  console.log('== LAYOUT ==');
  console.log(await ev(`(function(){
    const q=s=>document.querySelector(s).getBoundingClientRect();
    const h=q('header'), m=q('#mesa'), l=q('aside');
    const cards=[...document.querySelectorAll('#mesa .el')].map(c=>{const r=c.getBoundingClientRect();return {id:c.dataset.id,x:Math.round(r.left),y:Math.round(r.top),w:Math.round(r.width)}});
    const overflow=[...document.querySelectorAll('header *')].some(e=>e.scrollWidth>e.clientWidth+2);
    return {header:{w:Math.round(h.width),h:Math.round(h.height)}, mesa:{w:Math.round(m.width),h:Math.round(m.height)},
            lib:{w:Math.round(l.width),visible:l.right<=window.innerWidth+1},
            bodyScrollX: document.documentElement.scrollWidth<=window.innerWidth,
            headerOverflow: overflow, cards};
  })()`));

  console.log('\n== COLORES / ESTILO ==');
  console.log(await ev(`(function(){
    const g=(s,p)=>getComputedStyle(document.querySelector(s))[p];
    const card=document.querySelector('.el');
    return {logo:g('.logo','backgroundImage'), cardBg:g('.el','backgroundImage'), cardBorder:g('.el','borderTopColor'),
            panel:g('aside','backgroundImage').slice(0,40), bodyBg:g('body','backgroundColor'),
            cardShadow:g('.el','boxShadow').slice(0,60)};
  })()`));

  console.log('\n== DRAG canvas -> canvas (combinar) ==');
  console.log(await ev(`(function(){
