const { spawn } = require('child_process');
const FILE = '/var/tmp/bench/ws-9Tqt6ywi/alquimia-web-reactiva.html';
const PORT = 9700 + Math.floor(Math.random() * 200);
const chrome = spawn('google-chrome', ['--headless=new','--no-sandbox','--disable-gpu','--hide-scrollbars',
  '--remote-debugging-port='+PORT,'--user-data-dir=/tmp/opencode/cm-'+PORT,'file://'+FILE],{stdio:'ignore'});
const sleep = ms => new Promise(r=>setTimeout(r,ms));
(async()=>{
  let t=null;
  for(let i=0;i<60;i++){ await sleep(300); try{const l=await (await fetch(`http://127.0.0.1:${PORT}/json/list`)).json(); t=l.find(x=>x.type==='page'&&x.url.includes('alquimia')); if(t)break;}catch(e){} }
  const ws=new WebSocket(t.webSocketDebuggerUrl); let id=0; const pend=new Map(); const errs=[];
  const send=(m,p={})=>new Promise(r=>{const i=++id;pend.set(i,r);ws.send(JSON.stringify({id:i,method:m,params:p}));});
  ws.onmessage=e=>{const m=JSON.parse(e.data); if(m.id&&pend.has(m.id)){pend.get(m.id)(m.result);pend.delete(m.id);}
    if(m.method==='Runtime.exceptionThrown') errs.push(m.params.exceptionDetails.exception?.description||m.params.exceptionDetails.text);};
  await new Promise(r=>ws.onopen=r);
  await send('Runtime.enable'); await sleep(1000);
  const ev=async e=>{const r=await send('Runtime.evaluate',{expression:e,returnByValue:true});
    return r.exceptionDetails? {ERR:r.exceptionDetails.exception?.description||r.exceptionDetails.text}:r.result?.value;};

  for (const [w,h,label] of [[390,844,'iPhone 390'],[768,1024,'tablet 768'],[1920,1080,'desktop 1920']]) {
    await send('Emulation.setDeviceMetricsOverride',{width:w,height:h,deviceScaleFactor:1,mobile:w<600});
    await sleep(400);
    const r = await ev(`(function(){
      const R=s=>{const e=document.querySelector(s); if(!e) return null; const r=e.getBoundingClientRect(); return {x:Math.round(r.left),y:Math.round(r.top),w:Math.round(r.width),h:Math.round(r.height)};};
      const btn=[...document.querySelectorAll('.tools .btn')].map(b=>{const r=b.getBoundingClientRect();return {t:b.textContent.trim().slice(0,10),x:Math.round(r.left),r:Math.round(r.right),w:Math.round(r.width)};});
      const last=btn[btn.length-1];
      const card=document.querySelector('#mesa .el'); const cr=card.getBoundingClientRect();
      const hint=document.querySelector('.hint').getBoundingClientRect();
      const desc=document.querySelector('.lib-desc');
      return {vp:[innerWidth,innerHeight], mesa:R('#mesa'), aside:R('aside'), toggle:getComputedStyle(document.getElementById('libtoggle')).display,
              scrollX: document.documentElement.scrollWidth<=innerWidth,
              headerBtns:btn, ultimoBtnDerecha:last.r, headerW:Math.round(document.querySelector('header').getBoundingClientRect().width),
              cardTop:Math.round(cr.top), hintBottom:Math.round(hint.bottom), solapa: cr.top < hint.bottom,
              descVisible: desc.offsetHeight>0};
    })()`);
    console.log('== '+label+' ==');
    console.log(JSON.stringify(r,null,1));
  }
  console.log('\n== ERRORES ==', errs.length?errs:'ninguno');
  ws.close(); chrome.kill(); process.exit(0);
})().catch(e=>{console.error(e);chrome.kill();process.exit(1)});

parts.text:
At 390px the header fits (last button right edge 381 < 390). But the brand title is squeezed. Let's check: brand at left, stats... The stats (nDesc) — at 390 the `.stats` might be squeezed. The buttons start at x=132, so brand occupies 0..~130. The stats would need space between brand and buttons. Hmm, `.stats` has `margin-left:auto` so it's pushed right; but buttons come after. With brand ~130px + stats (~50) + buttons (249) = 429 > 390. Yet the last button is at 381, so something is being compressed. The stats may be overlapping or squeezed.

Wait — headerBtns shows "💡" at x=132. So brand ends around 120. Then where are the stats? The stats would be between the brand and tools, but `margin-left:auto` pushes stats right, then tools follow with margin-left:6px. So stats should be at ~... Actually the order in DOM is: brand, stats, tools. If stats has margin-left:auto, it pushes stats+tools to the right. So stats should be right before tools at x<132. So brand is 0..~85 and stats at 85..125.

Hmm, but brand h1 "Alquimia Web Reactiva" at 14px needs ~150px. It's probably overflowing/clipping. Let me check whether the brand title is truncated. `.brand` has `min-width:0` and `h1` has `white-space:nowrap` without overflow hidden → it will overflow.

Let me check the actual widths of brand/stats at 390 and see if there's overlap.

Let me improve the mobile header: at <=560px, hide the h1 text or shrink it, show only the logo + short title. Let me make the title shorter on mobile via CSS (can't change text with CSS easily... I could use a data attribute + ::after). Simpler: at <=560px, hide the "nTot"/bar (already) and let the brand shrink with overflow hidden + text-overflow ellipsis on h1.

Let me measure and then decide. Let me add to the CSS:
```css
@media (max-width:560px){
  .brand{min-width:0;flex:1 1 auto;overflow:hidden}
  .brand h1{font-size:13px;overflow:hidden;text-overflow:ellipsis}
  .brand > div{min-width:0}
  .stats{flex:0 0 auto}
}
```
And at <=420px, maybe hide the "descubiertos" label.

Let me measure the overlap first.

